import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
C='LEG-AMB'
E(C,'M1-Z01','Precauzione, prevenzione, «chi inquina paga»',[CL("Quale principio?","Seleziona una situazione, poi il principio che la ispira.",["Precauzione","Prevenzione e correzione alla fonte","Chi inquina paga"],[
 ["Si limita l’uso di una sostanza sospetta prima che i dati scientifici siano definitivi",0,"Si agisce anche in presenza di incertezza su un rischio grave."],
 ["L’impresa che ha contaminato il terreno sostiene i costi della bonifica",2,"I costi del ripristino gravano su chi ha causato l’inquinamento."],
 ["Si installa un filtro sul camino invece di intervenire sulle conseguenze",1,"Il danno si corregge in via prioritaria alla fonte."],
 ["Si sostituisce un solvente pericoloso con uno a base d’acqua",1,"Evitare il danno è preferibile a ripararlo."],
 ["La tariffa dei rifiuti cresce con la quantità prodotta",2,"Il costo è proporzionale all’impatto generato."],
 ["Si sospende un progetto in attesa di studi su un possibile danno irreversibile",0,"È l’applicazione tipica della precauzione."]],
 "Sei situazioni. Riconosci il principio del diritto ambientale che le ispira.","Art. 191 TFUE · art. 3-ter D.lgs. 152/2006")])
E(C,'M1-Z02','AUA: titoli compresi, durata e modifiche',[CL("Rientra nell’AUA?","Seleziona un titolo, poi la risposta.",["Rientra nell’AUA","Non rientra"],[
 ["Autorizzazione agli scarichi idrici",0,"È tra i titoli del D.P.R. 59/2013."],["Autorizzazione alle emissioni in atmosfera dell’art. 269",0,"Rientra."],
 ["Comunicazione di impatto acustico",0,"Rientra."],["Comunicazione per il recupero di rifiuti in procedura semplificata",0,"Rientra (artt. 214-216)."],
 ["Autorizzazione integrata ambientale",1,"L’AUA si applica agli impianti non soggetti ad AIA."],["Certificato di prevenzione incendi",1,"È un procedimento dei Vigili del fuoco, non ambientale."],
 ["Autorizzazione unica degli impianti di gestione dei rifiuti (art. 208)",1,"Non è compresa nell’AUA."],["Uso agronomico degli effluenti di allevamento",0,"Rientra."]],
 "Otto titoli abilitativi. Indica quali possono confluire nell’autorizzazione unica ambientale.","D.P.R. 59/2013, art. 3")])
E(C,'M1-Z03','Il procedimento di AUA: soggetti e tempi',[LB("Laboratorio · La domanda di AUA della carpenteria","Una carpenteria metallica con 40 addetti apre un nuovo stabilimento e ti chiede di impostare la domanda di AUA.",[
  ["Attività","taglio, saldatura e verniciatura di strutture in acciaio"],["Emissioni","fumi di saldatura aspirati e convogliati; cabina di verniciatura"],["Acque","servizi igienici e lavaggio pezzi in fognatura"],["Rumore","compressori e lavorazioni esterne, area mista con abitazioni vicine"],["Rifiuti","nessun recupero in procedura semplificata"]],[
  ("Quali titoli confluiscono nella domanda di AUA?",6,"Autorizzazione alle emissioni in atmosfera per saldatura e verniciatura, o adesione all’autorizzazione generale se l’attività vi rientra; autorizzazione allo scarico delle acque di lavaggio in fognatura; documentazione di impatto acustico. Gli scarichi dei servizi igienici in fognatura non richiedono autorizzazione.",["Ho indicato emissioni e scarico industriale","Ho indicato l’impatto acustico","Ho escluso gli scarichi domestici in fognatura"]),
  ("Descrivi il percorso della domanda: a chi si presenta, chi decide, in quanto tempo.",6,"Si presenta al SUAP, che la trasmette all’autorità competente, di norma la Provincia o l’ente individuato dalla Regione. Partecipano ARPA, Comune e gestore del servizio idrico. Il termine è di 90 giorni, o 120 se ci sono titoli con termini superiori; le richieste di integrazione sospendono i termini.",["Ho indicato SUAP e autorità competente","Ho indicato i soggetti coinvolti","Ho indicato i termini e la sospensione"]),
  ("Quali scadenze e regole sulle modifiche devi segnalare all’impresa?",6,"L’AUA dura 15 anni dal rilascio; la domanda di rinnovo va presentata almeno 6 mesi prima della scadenza. Le modifiche vanno comunicate: quelle sostanziali richiedono una nuova domanda. Vanno pianificati gli autocontrolli prescritti.",["Ho indicato i 15 anni e il rinnovo a 6 mesi","Ho distinto modifiche sostanziali e non","Ho previsto gli autocontrolli"])],
 "Il laboratorio simula l’impostazione di una domanda di autorizzazione unica ambientale per una carpenteria. Individua i titoli, descrivi il procedimento e segnala scadenze e regole sulle modifiche, poi confronta le tue risposte con la soluzione di riferimento.","D.P.R. 59/2013")])
E(C,'M1-Z04','Esempio applicativo: il censimento delle sorgenti di emissione',[LB("Laboratorio · Il censimento di una falegnameria","Censisci le sorgenti di emissione di una falegnameria che produce mobili.",[
  ["E1","aspirazione di trucioli e polveri di legno con filtro a maniche"],["E2","cabina di verniciatura a spruzzo con prodotti a solvente"],["E3","caldaia a biomassa legnosa da 400 kW per il riscaldamento"],["Diffuse","carteggiatura manuale vicino al portone, appassimento dei pezzi verniciati"]],[
  ("Classifica le sorgenti in convogliate e diffuse e indica gli inquinanti principali.",6,"Convogliate: E1, polveri di legno; E2, composti organici volatili e polveri di overspray; E3, polveri, ossidi di azoto e monossido di carbonio. Diffuse: carteggiatura manuale, polveri; appassimento, composti organici volatili.",["Ho distinto convogliate e diffuse","Ho associato gli inquinanti a ogni sorgente","Ho considerato l’appassimento"]),
  ("Quale regime autorizzativo valuti per lo stabilimento?",6,"Si verifica se le attività rientrano tra quelle in deroga o nelle autorizzazioni di carattere generale dell’art. 272, in base ai quantitativi di prodotti vernicianti e alla potenza degli impianti; altrimenti serve l’autorizzazione dell’art. 269, di norma nell’AUA. La caldaia a biomassa sotto 1 MW va valutata secondo l’Allegato IV alla Parte V.",["Ho considerato l’art. 272","Ho indicato l’art. 269 come alternativa","Ho considerato i quantitativi di prodotti"]),
  ("Quali misure riduci le emissioni diffuse?",6,"Spostare la carteggiatura in una postazione aspirata; appassimento in area chiusa e aspirata; prodotti a base d’acqua o ad alto residuo secco; manutenzione e controllo del differenziale di pressione del filtro a maniche; registro dei consumi dei prodotti vernicianti.",["Ho previsto la captazione delle diffuse","Ho previsto prodotti a minore contenuto di solventi","Ho previsto manutenzione e registri"])],
 "In questo laboratorio censisci le sorgenti di emissione di una falegnameria. Classifica le sorgenti, valuta il regime autorizzativo e proponi misure per le emissioni diffuse, poi confronta le tue risposte con la soluzione di riferimento.","D.lgs. 152/2006, artt. 269 e 272 · Allegato IV alla Parte V")])
E(C,'M1-Z05','I medi impianti di combustione',[ES("Esempio guidato · Quando si adegua il generatore?","Le scadenze per i medi impianti di combustione esistenti.",[
 ["L’impianto","Un generatore di vapore esistente da 3 MW alimentato a gas naturale.","1 MW ≤ 3 MW < 50 MW → medio impianto"],
 ["La classe","Gli impianti esistenti fino a 5 MW si adeguano ai nuovi valori limite dal 1° gennaio 2030.","Adeguamento dal 2030"],
 ["Il confronto","Un generatore esistente da 8 MW avrebbe dovuto adeguarsi dal 1° gennaio 2025.","Oltre 5 MW → dal 2025"],
 ["Un impianto nuovo","Un generatore installato oggi rispetta i valori limite da subito.","Nuovi: dal 20 dicembre 2018"],
 ["Gli obblighi","Iscrizione nel registro degli impianti e monitoraggio periodico delle emissioni.","Registro e monitoraggio"]],
 "Vediamo le scadenze per i medi impianti di combustione. Un generatore esistente da tre megawatt è un medio impianto e si adegua ai nuovi valori limite dal primo gennaio duemilatrenta. Se fosse da otto megawatt, la scadenza sarebbe stata il primo gennaio duemilaventicinque. Un impianto nuovo rispetta i limiti da subito. In ogni caso servono l’iscrizione nel registro e il monitoraggio periodico.","Direttiva (UE) 2015/2193 · art. 273-bis D.lgs. 152/2006")])
E(C,'M1-Z06','Il sistema europeo di scambio delle quote di emissione',[ES("Esempio guidato · Il conto delle quote","Un impianto ETS e il suo bilancio annuale.",[
 ["Le emissioni","Le emissioni verificate dell’anno sono 12.400 t CO₂.","12.400 t"],
 ["La comunicazione","La comunicazione delle emissioni verificate si presenta entro il 31 marzo dell’anno successivo.","Entro il 31 marzo"],
 ["Le quote gratuite","L’impianto ha ricevuto 8.000 quote gratuite.","8.000 quote"],
 ["Il fabbisogno","Mancano 12.400 − 8.000 = 4.400 quote, da acquistare sul mercato.","4.400 quote da acquistare"],
 ["La restituzione","Le quote si restituiscono entro il 30 settembre; con un prezzo indicativo di 70 € per quota il costo è di circa 308.000 €.","Prezzo illustrativo"]],
 "Facciamo il conto delle quote di un impianto. Le emissioni verificate sono dodicimilaquattrocento tonnellate e si comunicano entro il trentuno marzo. L’impianto ha ottomila quote gratuite: ne mancano quattromilaquattrocento, da acquistare. Le quote si restituiscono entro il trenta settembre. Con un prezzo indicativo di settanta euro, il costo è di circa trecentottomila euro.","Direttiva 2003/87/CE come modificata dalla Dir. (UE) 2023/959")])
E(C,'M1-Z07','Gas fluorurati e sostanze che riducono lo strato di ozono',[SC("Il chiller del reparto","Il chiller del reparto contiene 60 kg di R-410A, pari a circa 125 t CO₂e. Il tecnico trova una perdita durante il controllo.",[
 ("Con quale frequenza va controllato per le perdite?",[["Ogni 6 mesi, oppure ogni 12 mesi se dotato di sistema di rilevamento delle perdite",True,"Corretto: tra 50 e 500 t CO₂e il controllo è semestrale, annuale con un sistema di rilevamento."],["Ogni 3 mesi",False,"È la frequenza da 500 t CO₂e in su."],["Ogni 5 anni",False,"La frequenza è molto più ravvicinata."]]),
 ("Che cosa si fa dopo la riparazione della perdita?",[["Nulla",False,"Serve un controllo di verifica."],["Un nuovo controllo dopo almeno 24 ore ed entro un mese dalla riparazione",True,"Corretto: verifica l’efficacia della riparazione."],["Si aggiunge refrigerante senza cercare la perdita",False,"Ricaricare senza riparare è vietato."]]),
 ("Quali registrazioni servono?",[["Registro dell’apparecchiatura e comunicazione dell’intervento alla Banca dati entro 30 giorni",True,"Corretto: lo prevede il D.P.R. 146/2018."],["Nessuna, se l’impresa è certificata",False,"Le registrazioni sono sempre dovute."],["Solo la fattura del tecnico",False,"Non basta."]])],
 "Frequenza dei controlli in base alle tonnellate di CO₂ equivalente, verifica dopo la riparazione, registrazione e comunicazione alla Banca dati: è la gestione corretta di un’apparecchiatura con gas fluorurati.","Una perdita su un chiller. Gestiscila secondo il regolamento F-gas.","Reg. (UE) 2024/573 · D.P.R. 146/2018")])
E(C,'M1-Z08','AIA: riesame e direttiva sulle emissioni industriali',[ES("Esempio guidato · Quando si riesamina l’AIA?","Le due scadenze del riesame.",[
 ["Il titolo","Un’installazione ha ottenuto l’AIA nel 2020 ed è registrata EMAS.","AIA 2020, EMAS"],
 ["Le BAT","Nel 2025 sono pubblicate le nuove conclusioni sulle BAT della sua attività principale.","Pubblicazione 2025"],
 ["Primo riesame","Entro 4 anni dalla pubblicazione delle conclusioni sulle BAT: entro il 2029.","Riesame entro 4 anni"],
 ["Riesame con valenza di rinnovo","Ordinariamente ogni 10 anni; 12 con UNI EN ISO 14001; 16 con EMAS.","EMAS → 16 anni"],
 ["La conseguenza","Il riesame per le BAT arriva prima: l’installazione deve adeguarsi ai nuovi BAT-AEL.","Adeguamento ai BAT-AEL"]],
 "Vediamo le scadenze del riesame dell’AIA. L’installazione ha l’AIA dal duemilaventi ed è registrata EMAS. Nel duemilaventicinque escono nuove conclusioni sulle BAT: entro quattro anni l’autorizzazione va riesaminata. Il riesame con valenza di rinnovo, ordinariamente decennale, per le installazioni EMAS è di sedici anni. Il riesame legato alle BAT arriva prima e impone l’adeguamento ai nuovi livelli di emissione.","Art. 29-octies D.lgs. 152/2006")])
E(C,'M1-Z09','VIA: verifica di assoggettabilità e provvedimento unico',[SC("L’ampliamento dello stabilimento","Un’impresa vuole raddoppiare la capacità produttiva di uno stabilimento già autorizzato, ampliando i capannoni su un’area agricola confinante.",[
 ("Che cosa verifichi per primo?",[["Se il progetto rientra negli allegati alla Parte II per la VIA o per la verifica di assoggettabilità",True,"Corretto: il primo passo è la classificazione del progetto."],["Nulla: lo stabilimento è già autorizzato",False,"Le modifiche e gli ampliamenti possono richiedere una valutazione."],["Solo il permesso di costruire",False,"Non basta."]]),
 ("Il progetto rientra nell’Allegato IV. Che cosa comporta?",[["La verifica di assoggettabilità a VIA, che può concludersi con l’esclusione o con l’obbligo di VIA",True,"Corretto: è lo screening dell’art. 19."],["La VIA obbligatoria in ogni caso",False,"Per l’Allegato IV si parte dalla verifica."],["Nessun procedimento",False,"Serve la verifica."]]),
 ("Se serve la VIA, come si ottengono anche gli altri titoli?",[["Con il provvedimento autorizzatorio unico regionale, che riunisce i titoli necessari",True,"Corretto: art. 27-bis."],["Con domande separate dopo la VIA",False,"Il PAUR evita procedimenti separati."],["Con un’autocertificazione",False,"Non è ammessa."]])],
 "Classificare il progetto, passare dalla verifica di assoggettabilità quando previsto, usare il provvedimento unico: così si affronta un ampliamento significativo.","Un raddoppio della capacità produttiva. Individua il percorso di valutazione.","D.lgs. 152/2006, Parte II, artt. 19 e 27-bis")])
E(C,'M1-Z10','Seveso III: gli stabilimenti a rischio di incidente rilevante',[CL("Soglia inferiore o superiore?","Seleziona un obbligo, poi a quali stabilimenti si applica.",["Tutti gli stabilimenti Seveso","Solo soglia superiore"],[
 ["Notifica, aggiornata a ogni modifica",0,"Vale per tutti."],["Politica di prevenzione degli incidenti rilevanti",0,"Vale per tutti."],
 ["Rapporto di sicurezza riesaminato almeno ogni 5 anni",1,"Solo per la soglia superiore."],["Piano di emergenza interna",1,"Obbligo della soglia superiore."],
 ["Sistema di gestione della sicurezza",0,"Per tutti, con contenuti proporzionati."],["Ispezioni almeno annuali",1,"Annuali per la soglia superiore, triennali per l’inferiore."]],
 "Sei obblighi della direttiva Seveso III. Indica se valgono per tutti gli stabilimenti o solo per quelli di soglia superiore.","D.lgs. 105/2015")])
E(C,'M1-Z11','Il registro delle prescrizioni legali e autorizzative',[LB("Laboratorio · Costruire il registro delle prescrizioni","Costruisci le prime righe del registro delle prescrizioni per uno stabilimento di trattamento superficiale.",[
  ["AUA","rilasciata il 10 marzo 2022: emissioni da due camini con autocontrollo annuale; scarico industriale in fognatura con autocontrollo semestrale"],["F-gas","chiller da 125 t CO₂e"],["Rifiuti","fanghi di depurazione pericolosi, oli esausti"],["Rumore","valutazione di impatto acustico del 2022"]],[
  ("Scrivi le righe del registro per emissioni e scarico: prescrizione, frequenza, responsabile, evidenza.",8,"Emissioni E1 ed E2: autocontrollo annuale dei parametri prescritti; responsabile ambiente; evidenza: rapporti di prova e comunicazione all’autorità se prevista. Scarico: autocontrollo semestrale nel pozzetto fiscale; responsabile ambiente; evidenza: verbale di campionamento e rapporto di prova. Rinnovo AUA: domanda entro il 10 settembre 2036.",["Ho indicato frequenze e responsabili","Ho indicato le evidenze documentali","Ho calcolato il termine per il rinnovo"],None,150),
  ("Aggiungi le righe per gas fluorurati e rifiuti.",7,"Chiller: controllo delle perdite semestrale, o annuale con sistema di rilevamento, da tecnico certificato; registro dell’apparecchiatura e comunicazione alla Banca dati entro 30 giorni. Rifiuti: iscrizione al RENTRI, registro digitale con annotazioni entro 10 giorni lavorativi e trasmissione mensile, formulari digitali, verifica delle accettazioni entro tre mesi, MUD annuale.",["Ho inserito frequenza e registrazioni F-gas","Ho inserito gli adempimenti RENTRI","Ho inserito il MUD"],None,120),
  ("Quali eventi devono far aggiornare il registro?",5,"Nuove norme o modifiche normative; nuove autorizzazioni, rinnovi o prescrizioni; modifiche di impianti e processi; esiti di controlli e audit; cambi di responsabile. L’aggiornamento va datato e approvato.",["Ho indicato modifiche normative e autorizzative","Ho indicato modifiche impiantistiche","Ho previsto data e approvazione"])],
 "Il laboratorio ti chiede di costruire le prime righe di un registro delle prescrizioni per uno stabilimento reale. Compila le righe per emissioni e scarico, poi per gas fluorurati e rifiuti, e indica quando aggiornare il registro. Confronta ogni risposta con la soluzione di riferimento.","UNI EN ISO 14001:2015, punti 6.1.3 e 9.1.2")])
E(C,'M1-Z12','La valutazione periodica della conformità',[LB("Laboratorio · L’audit di conformità","Durante la valutazione periodica della conformità hai raccolto cinque rilievi.",[
  ["Rilievo 1","autocontrollo del camino E2 eseguito con 4 mesi di ritardo"],["Rilievo 2","registro del chiller aggiornato e controlli regolari"],["Rilievo 3","due formulari senza conferma di accettazione da oltre tre mesi"],["Rilievo 4","il deposito di fanghi non riporta l’etichetta di pericolo"],["Rilievo 5","la valutazione di impatto acustico non considera il nuovo compressore"]],[
  ("Classifica i rilievi: conforme, non conformità, opportunità di miglioramento.",6,"Rilievo 2: conforme. Rilievi 1, 3 e 4: non conformità rispetto a prescrizioni e norme. Rilievo 5: non conformità potenziale, perché la modifica impiantistica non è stata valutata; va verificata con una nuova valutazione acustica.",["Ho riconosciuto il rilievo conforme","Ho classificato le non conformità","Ho valutato il rilievo 5"]),
  ("Per ogni non conformità indica correzione immediata e azione correttiva.",8,"1: eseguire subito l’autocontrollo; scadenzario con promemoria. 3: chiedere le conferme e, se non arrivano, comunicare all’autorità secondo l’art. 188; controllo mensile dei formulari aperti. 4: etichettare subito; checklist del deposito. 5: nuova valutazione di impatto acustico; procedura di gestione delle modifiche.",["Ho distinto correzione e azione correttiva","Ho indicato le comunicazioni dovute","Ho previsto controlli sistematici"],None,150),
  ("Riassumi l’esito per la direzione in poche righe.",5,"Su cinque aspetti verificati, uno conforme e quattro con criticità, di cui una legata alla gestione delle modifiche. Nessun superamento di limiti accertato. Servono uno scadenzario unico, il controllo mensile dei formulari e una procedura per le modifiche. Proposta: verifica di efficacia tra tre mesi.",["Ho dato un quadro sintetico","Ho indicato le priorità","Ho proposto una verifica di efficacia"])],
 "Nel laboratorio valuti cinque rilievi raccolti durante una valutazione di conformità. Classificali, indica correzioni e azioni correttive e scrivi una breve sintesi per la direzione, poi confronta ogni risposta con la soluzione di riferimento.","UNI EN ISO 14001:2015, punti 9.1.2 e 10.2"),
 AP("Il quadro autorizzativo della tua azienda","Ricostruisci i titoli ambientali della tua organizzazione.",["AUA o autorizzazioni settoriali","AIA","Autorizzazione allo scarico","Autorizzazione o adesione per le emissioni","Iscrizione al RENTRI","Registro delle apparecchiature F-gas","Registro delle prescrizioni"],"La prossima scadenza ambientale e chi la presidia","Es.: rinnovo AUA a settembre 2030, responsabile ambiente",
  "Ricostruisci il quadro autorizzativo della tua azienda e indica la prossima scadenza ambientale e chi la presidia.",3)])
E(C,'M1-Z13','Inventari e registri delle emissioni',[SC("I dati che non tornano","Preparando la dichiarazione annuale delle emissioni ti accorgi che i composti organici volatili calcolati con il piano di gestione dei solventi sono il doppio di quelli stimati dagli autocontrolli ai camini.",[
 ("Quale spiegazione è più probabile?",[["Le emissioni diffuse, che gli autocontrolli ai camini non misurano",True,"Corretto: il piano di gestione dei solventi considera anche le emissioni diffuse."],["Un errore del laboratorio, sicuramente",False,"Prima di concluderlo servono verifiche."],["Nessuna: si dichiara il valore più basso",False,"Dichiarare dati non coerenti è un rischio."]]),
 ("Che cosa dichiari?",[["Il dato più completo e documentato, spiegando il metodo di stima",True,"Corretto: coerenza e tracciabilità del metodo sono essenziali."],["La media dei due valori",False,"Non ha fondamento tecnico."],["Nulla quest’anno",False,"La dichiarazione è un obbligo."]]),
 ("Che cosa fai per il futuro?",[["Rivedi il piano di gestione dei solventi e valuti la captazione delle emissioni diffuse",True,"Corretto: ridurre le diffuse migliora conformità e dati."],["Aumenti la frequenza delle analisi ai camini e basta",False,"Non misura le diffuse."],["Smetti di calcolare il piano",False,"È uno strumento richiesto."]])],
 "Dati coerenti tra dichiarazioni, autocontrolli e piano di gestione dei solventi, con metodi documentati: è la base di ogni inventario credibile.","Due stime delle emissioni non coincidono. Decidi che cosa dichiarare.","Reg. (CE) 166/2006 · Reg. (UE) 2024/1244 · art. 275 D.lgs. 152/2006")])
